define(["theme_worldcampus/accessibilitysettings_modal","jquery"],function(t,e){return{init:function(){e("#accessibilitysettings-control").click(function(e){e.preventDefault(),t.create({}).then(function(t){t.show()}).catch(function(t){console.error("Accessibility Modal Error:",t)})})}}});